SELECT s.user_id,s.id,s.points_awarded,CONCAT('Approved: ',c.title),s.reviewer_id,COALESCE(s.reviewed_at,s.created_at)
FROM submissions s JOIN challenges c ON c.id=s.challenge_id
WHERE s.status='approved' AND s.id BETWEEN 1 AND 74
AND NOT EXISTS (SELECT 1 FROM point_transactions p WHERE p.submission_id=s.id);


SELECT ca.user_id,c.bonus_points,CONCAT('Campaign completed: ',c.name),2,ca.awarded_at
FROM campaign_awards ca JOIN campaigns c ON c.id=ca.campaign_id
WHERE c.id IN (1,2) AND NOT EXISTS (
SELECT 1 FROM point_transactions p WHERE p.user_id=ca.user_id
AND p.reason=CONCAT('Campaign completed: ',c.name) AND p.submission_id IS NULL);

SELECT ca.user_id,c.achievement_id
FROM campaign_awards ca JOIN campaigns c ON c.id=ca.campaign_id
WHERE c.id=1 AND c.achievement_id IS NOT NULL;


COMMIT;




